#!/usr/bin/env python3
"""Writes Sources/MatildeKit/SyncCrypto/MatildeKeyWords.swift from bip39-english.txt."""
import hashlib
import os

HERE = os.path.dirname(os.path.abspath(__file__))
EXPECTED = "2f5eed53a4727b4bf8880d8f3f199efc90e58503646d9ff8eff3a2ed3b24dbda"

with open(os.path.join(HERE, "bip39-english.txt"), "rb") as handle:
    raw = handle.read()
assert hashlib.sha256(raw).hexdigest() == EXPECTED, "not the published BIP-0039 English list"
words = raw.decode().split("\n")[:-1]
assert len(words) == 2048

lines = [
    "// Generated by packages/MatildeKit/Wordlists/generate.py from bip39-english.txt. Do not edit.",
    "// The BIP-0039 English wordlist (bitcoin/bips; also in trezor/python-mnemonic, MIT License,",
    "// Copyright (c) 2013 Pavol Rusnak). See packages/MatildeKit/Wordlists/README.md.",
    "",
    "enum MatildeKeyWords {",
    "    /// 2048 words, sorted; each is identified by its first four letters.",
    "    static let english: [String] = [",
]
for start in range(0, 2048, 8):
    lines.append("        " + ", ".join(f'"{w}"' for w in words[start:start + 8]) + ",")
lines += ["    ]", "}", ""]
with open(os.path.join(HERE, "..", "Sources", "MatildeKit", "SyncCrypto", "MatildeKeyWords.swift"), "w") as handle:
    handle.write("\n".join(lines))
